def get_magic_bytes():
    lines=["<b>🔮 File Signatures (Magic Bytes)</b>\n"]
    for sig,name in MAGIC_BYTES.items(): lines.append(f"<code>{sig}</code> — {name}")
    return "\n".join(lines)
def lookup_port(port): return {"port":port,"service":COMMON_PORTS.get(port,"Unknown"),"known":port in COMMON_PORTS}
def get_ports_table():
    lines=["<b>🔌 Well-Known Ports</b>\n"]
    for port,service in sorted(COMMON_PORTS.items()): lines.append(f"<code>{port:5d}</code> — {service}")
    return "\n".join(lines)
def lookup_http_status(code): return {"code":code,"description":HTTP_STATUS.get(code,"Unknown status code"),"category":{1:"Informational",2:"Success",3:"Redirection",4:"Client Error",5:"Server Error"}.get(code//100,"Unknown")}
def get_owasp(): return OWASP
def generate_reverse_shell(ip,port,shell_type="bash"):
    if shell_type not in REVERSE_SHELLS: return f"Unknown type. Available: {', '.join(REVERSE_SHELLS.keys())}"
    cmd=REVERSE_SHELLS[shell_type].format(ip=ip,port=port)
    return {"type":shell_type,"ip":ip,"port":port,"command":cmd,"listener":f"nc -lvnp {port}","note":"⚠️ For authorised penetration testing and CTF use only"}
def get_sqli_payloads(t="all"): return {"types":list(SQLi.keys()),"payloads":SQLi} if t=="all" else (f"Unknown. Available: {', '.join(SQLi.keys())}" if t not in SQLi else {"type":t,"payloads":SQLi[t]})
def get_xss_payloads(ctx="all"): return {"contexts":list(XSS.keys()),"payloads":XSS} if ctx=="all" else (f"Unknown. Available: {', '.join(XSS.keys())}" if ctx not in XSS else {"context":ctx,"payloads":XSS[ctx]})
def get_lfi_payloads(): return {"count":len(LFI),"payloads":LFI}
def get_ssti_payloads(engine="detection"): return f"Unknown engine. Available: {', '.join(SSTI.keys())}" if engine not in SSTI else {"engine":engine,"payloads":SSTI[engine],"note":"If {{7*7}} returns 49, SSTI is confirmed"}
